'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { CalendarCheck, AlertTriangle } from 'lucide-react';

export default function MyAttendancePage() {
    const [data, setData] = useState<any>(null);

    useEffect(() => {
        const load = async () => {
            try {
                const res = await api.get<any>('/api/student/attendance');
                if (res.success) setData(res.data);
            } catch (e) { }
        };
        load();
    }, []);

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>
                My Attendance
            </h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>View your attendance across all subjects</p>

            {!data || !data.summary || data.summary.length === 0 ? (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <CalendarCheck size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>No attendance records found</p>
                </div>
            ) : (
                <>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 16, marginBottom: 24 }}>
                        {data.summary.map((s: any, i: number) => (
                            <div key={i} className="card" style={{ padding: 24, borderLeft: `4px solid ${s.flagged ? '#ef4444' : '#10b981'}` }}>
                                <div style={{ fontSize: 13, color: '#8a9aa2', marginBottom: 8 }}>Subject: {s.subject_id}</div>
                                <div style={{ fontSize: 32, fontWeight: 800, color: s.flagged ? '#ef4444' : '#142B34', fontFamily: 'Poppins' }}>
                                    {s.percentage}%
                                </div>
                                <div style={{ fontSize: 13, color: '#5a6a72', marginTop: 4 }}>
                                    {s.present}/{s.total_sessions} sessions
                                </div>
                                {s.flagged && (
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 8, color: '#ef4444', fontSize: 12, fontWeight: 600 }}>
                                        <AlertTriangle size={14} /> Below 75% — Defaulter
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </>
            )}
        </div>
    );
}
